import {LocalNotifications} from '@capacitor/local-notifications'
import {nativePlatform} from './nativePlatform.ts'
/** Native Capacitor v8 LocalNotifications bridge.
 *
 * The Android project is generated by scripts/setup-android.mjs, which
 * installs @capacitor/local-notifications@8.3.1 and registers its native plugin.
 * On hosted web pages no Android notification is scheduled.
 */
import {buildReminderPlan,isPayTaktReminderId,type ReminderPreferences} from './reminderPlan.ts'
import type {Shift} from './calendar.ts'
import type {PaySettings} from './salary.ts'

type NotificationRecord={
  id:number;title:string;body:string
  schedule?:{at:Date;allowWhileIdle?:boolean}
  isExactNotification?:boolean
  extra?:Record<string,unknown>
}
type NativePlugin={
  checkPermissions():Promise<{display:string}>
  requestPermissions():Promise<{display:string}>
  getPending():Promise<{notifications:{id:number;extra?:Record<string,unknown>}[]}>
  cancel(value:{notifications:{id:number}[]}):Promise<void>
  schedule(value:{notifications:NotificationRecord[]}):Promise<unknown>
  createChannel?(channel:{id:string;name:string;importance:3;description:string}):Promise<void>
}
type CapacitorBridge={
  isNativePlatform?:()=>boolean
  getPlatform?:()=>string
  Plugins?:{LocalNotifications?:NativePlugin}
}
const CHANNEL='paytakt-reminders'
export function androidNotifications():NativePlugin|null{
  if(typeof window==='undefined')return null
  const cap=(window as Window&{Capacitor?:CapacitorBridge}).Capacitor
  if(!cap?.isNativePlatform?.()||!['android','ios'].includes(cap.getPlatform?.()??''))return null
  return cap.Plugins?.LocalNotifications??LocalNotifications
}
export async function requestRemindersPermission():Promise<void>{
  const plugin=androidNotifications()
  if(!plugin)throw Error('Сповіщення доступні лише у встановленому застосунку PayTakt.')
  const status=await plugin.requestPermissions()
  if(status.display!=='granted')throw Error('Дозвіл на сповіщення не надано. Його можна дозволити у налаштуваннях телефону.')
}
let chain:Promise<void>=Promise.resolve()
function runSerialized<T>(task:()=>Promise<T>):Promise<T>{
  const next=chain.then(task)
  chain=next.then(()=>undefined,()=>undefined)
  return next
}
async function cancelManaged(plugin:NativePlugin):Promise<void>{
  const pending=await plugin.getPending()
  const own=pending.notifications.filter(n=>isPayTaktReminderId(n.id)).map(n=>({id:n.id}))
  if(own.length)await plugin.cancel({notifications:own})
}
export function cancelPayTaktReminders():Promise<void>{
  const plugin=androidNotifications()
  return plugin?runSerialized(async()=>cancelManaged(plugin)):Promise.resolve()
}
/** Reconcile on app start, when a workspace changes, and on resume.
 * Important: never request permission from an effect; permission is opt-in.
 */
export function reconcileReminders(input:{
 uid:string;workspaceId:string;workspaceName:string
 shifts:readonly Shift[];pay:PaySettings|null;prefs:ReminderPreferences
 now?:Date
}):Promise<number>{
  const plugin=androidNotifications()
  if(!plugin)return Promise.resolve(0)
  return runSerialized(async()=>{
    const permission=await plugin.checkPermissions()
    // Disabling cancels our reminders even without active permission.
    await cancelManaged(plugin)
    if(!input.prefs.enabled)return 0
    if(permission.display!=='granted')
      throw Error('Сповіщення вимкнені у налаштуваннях телефону. Дозволь сповіщення для PayTakt.')
    const plan=buildReminderPlan(input.uid,input.workspaceId,input.workspaceName,input.shifts,input.pay,input.prefs,input.now)
    if(!plan.length)return 0
    try{
      if(nativePlatform()==='android')await plugin.createChannel?.({id:CHANNEL,name:'Нагадування PayTakt',importance:3,
        description:'Робочі зміни та заплановані виплати'})
    }catch{/* already exists or handled by default notification channel */}
    // Chunk to avoid large native bridge payloads. Exact alarms are not
    // requested; Android may deliver reminders several minutes late.
    for(let i=0;i<plan.length;i+=32){
      const part=plan.slice(i,i+32)
      await plugin.schedule({notifications:part.map(n=>({
        id:n.id,title:n.title,body:n.body,
        schedule:{at:n.at,...(nativePlatform()==='android'?{allowWhileIdle:true}:{})},
        ...(nativePlatform()==='android'?{isExactNotification:false}:{}), // Android 12+ no special exact-alarm permission
        extra:{paytaktReminder:true,workspaceId:input.workspaceId,eventKey:n.eventKey},
      }))})
    }
    return plan.length
  })
}
